 where i.id = v.id
   and i.site_id = 106
   and coalesce(i.extra->'photos', '[]'::jsonb) = '[]'::jsonb;

-- ---------- Перевірка ----------

select count(*) filter (where coalesce(extra->'photos','[]'::jsonb) <> '[]'::jsonb) as "товарів із галереєю",
       count(*) filter (where coalesce(image_url,'') <> '')                          as "товарів із фото",
       count(*)                                                                      as "усього"
  from public.items where site_id = 106 and collection = 'products';
